import { jsx as _jsx } from "react/jsx-runtime";
import { describe, it, expect } from "vitest";
import { render, waitFor, fireEvent } from "@testing-library/react";
import { userEvent } from "@testing-library/user-event";
import { Star } from "@mui/icons-material";
import { LocalActions } from "..";
describe("LocalActions", () => {
    it("has correct icons and menu opens and closes correctly", async () => {
        const { getByLabelText, getAllByLabelText, getAllByRole, queryAllByRole } = render(_jsx(LocalActions, { actions: [
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star",
                },
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star1",
                },
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star2",
                },
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star3",
                },
            ] }));
        const expandIcon = getByLabelText("expand");
        const icons = getAllByLabelText("star", { exact: false });
        expect(icons).toHaveLength(2);
        expect(expandIcon).toBeInTheDocument();
        const user = userEvent.setup();
        await user.click(expandIcon);
        const menuItems = await waitFor(() => getAllByRole("menuitem"));
        expect(menuItems).toHaveLength(2);
        await user.click(menuItems[0]);
        const menuItemsAfterClose = queryAllByRole("menuitem");
        expect(menuItemsAfterClose).toHaveLength(0);
    });
    it("has only icons is 3 actions are passed", () => {
        const { queryByLabelText, getAllByLabelText } = render(_jsx(LocalActions, { actions: [
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star",
                },
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star1",
                },
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star2",
                },
            ] }));
        const expandIcon = queryByLabelText("expand");
        const icons = getAllByLabelText("star", { exact: false });
        expect(icons).toHaveLength(3);
        expect(expandIcon).not.toBeInTheDocument();
    });
    it("has only the expand option if is set to be dropdown only", () => {
        const { getByLabelText, queryAllByLabelText } = render(_jsx(LocalActions, { actions: [
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star",
                },
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star1",
                },
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star2",
                },
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star3",
                },
            ], isDropdownOnly: true }));
        const expandIcon = getByLabelText("expand");
        const icons = queryAllByLabelText("star", { exact: false });
        expect(icons).toHaveLength(0);
        expect(expandIcon).toBeInTheDocument();
    });
    it("allows disabled options", async () => {
        const { getByLabelText, getAllByRole } = render(_jsx(LocalActions, { actions: [
                {
                    Icon: Star,
                    disabled: true,
                    onClick: () => { },
                    text: "Star",
                },
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star1",
                },
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star2",
                },
                {
                    Icon: Star,
                    disabled: true,
                    onClick: () => { },
                    text: "Star3",
                },
            ] }));
        expect(getAllByRole("button").at(0)?.getAttribute("disabled")).not.toBeNull();
        expect(getAllByRole("button").at(1)?.getAttribute("disabled")).toBeNull();
        const expandIcon = getByLabelText("expand");
        const user = userEvent.setup();
        await user.click(expandIcon);
        const menuItems = await waitFor(() => getAllByRole("menuitem"));
        expect(menuItems[0]?.getAttribute("aria-disabled")).toBeNull();
        expect(menuItems[1]?.getAttribute("aria-disabled")).not.toBeNull();
    });
    it("allows tooltips", async () => {
        const { getByLabelText, findByRole, getAllByRole } = render(_jsx(LocalActions, { actions: [
                {
                    Icon: Star,
                    disabled: true,
                    onClick: () => { },
                    text: "Star",
                    tooltip: "option 1",
                },
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star1",
                    tooltip: "option 2",
                },
                {
                    Icon: Star,
                    onClick: () => { },
                    text: "Star2",
                    tooltip: "option 3",
                },
                {
                    Icon: Star,
                    disabled: true,
                    onClick: () => { },
                    text: "Star3",
                    tooltip: "option 4",
                },
            ] }));
        fireEvent.mouseOver(getAllByRole("button").at(0));
        expect((await findByRole("tooltip")).textContent).toEqual("option 1");
        const expandIcon = getByLabelText("expand");
        const user = userEvent.setup();
        await user.click(expandIcon);
        fireEvent.mouseOver(getAllByRole("menuitem").at(0));
        expect((await findByRole("tooltip")).textContent).toEqual("option 3");
    });
});
